#include <cstdio>
#include <algorithm>
#include <limits>
using namespace std;

const int INF = 1000000;
const int maxn = 100;

int main() {
    int n, m, a, b, cost, time, k, p, q, r;
    int t[maxn][maxn], c[maxn][maxn];

    while (scanf("%d %d", &n, &m), n || m) {
        for (int i = 0; i < m; i++) {
            fill(t[i], t[i] + m, INF);
            fill(c[i], c[i] + m, INF);
            t[i][i] = c[i][i] = 0;
        }

        for (int i = 0; i < n; i++) {
            scanf("%d %d %d %d", &a, &b, &cost, &time);
            t[a - 1][b - 1] = min(t[a - 1][b - 1], time);
            c[a - 1][b - 1] = min(c[a - 1][b - 1], cost);
            t[b - 1][a - 1] = t[a - 1][b - 1];
            c[b - 1][a - 1] = c[a - 1][b - 1];
        }

        for (int x = 0; x < m; x++) {
            for (int i = 0; i < m; i++) {
                if (t[i][x] == INF) continue; // Skip if there's no path
                for (int j = 0; j < m; j++) {
                    if (t[x][j] == INF) continue; // Skip if there's no path
                    t[i][j] = min(t[i][j], t[i][x] + t[x][j]);
                    c[i][j] = min(c[i][j], c[i][x] + c[x][j]);
                }
            }
        }

        scanf("%d", &k);
        for (int i = 0; i < k; i++) {
            scanf("%d %d %d", &p, &q, &r);
            printf("%d\n", r ? t[p - 1][q - 1] : c[p - 1][q - 1]);
        }
    }
}

